<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import Sheet from '../components/Sheet.vue'
import OriginalCover from './OriginalCover.vue'
import {useLocal} from '../stores/local'
import {updateBookMetadata,groupsOf,type BookMetadata} from './library-management'
import {canonical,type Document,type LocalStory} from '../domain/local-contract'
import {BookOpen,Clapperboard,GitBranch,Users,NotebookPen} from 'lucide-vue-next'
import {mainLineKey,type MainReadingLine} from '../writing/main-line'
const mainBranch=ref<string|null>(null),linksReady=ref(false)
const props=defineProps<{book:Document<LocalStory>}>(),emit=defineEmits<{close:[];saved:[];remove:[];cover:[]}>(),store=useLocal()
const title=ref(props.book.value.title),tags=ref(props.book.value.tags.join('，')),groups=ref(groupsOf(props.book.value).join('，')),pinned=ref(!!props.book.value.pinned),favorite=ref(props.book.value.favorite),error=ref(''),saving=ref(false),sourceBytes=ref<number|null>(null),added=ref('')
const base=ref(props.book),latest=ref<Document<LocalStory>|null>(null)
let disposed=false,intent:{operationId:string;signature:string;book:Document<LocalStory>;patch:BookMetadata}|null=null
const split=(value:string)=>value.split(/[,，\n]/).map(s=>s.trim()).filter(Boolean)
async function save(){const vault=store.vault;if(!vault||saving.value)return;saving.value=true;error.value='';const patch:BookMetadata={title:title.value.trim(),tags:split(tags.value),groups:split(groups.value),pinned:pinned.value,favorite:favorite.value},signature=canonical(patch);if(!intent||intent.signature!==signature)intent={operationId:crypto.randomUUID(),signature,book:base.value,patch};const current=intent;try{await updateBookMetadata(vault,current.operationId,[current.book],current.patch);if(!disposed&&store.vault===vault)emit('saved')}catch(e){if(!disposed){error.value=(e as Error).message;if((e as {code?:string}).code==='REVISION_CONFLICT'){const row=await vault.read<LocalStory>(props.book.id);if(!disposed&&store.vault===vault&&row?.kind==='story')latest.value=row}}}finally{if(!disposed)saving.value=false}}
function useLatest(){if(!latest.value)return;base.value=latest.value;latest.value=null;intent=null;error.value=''}
onMounted(async()=>{const vault=store.vault;if(!vault)return;try{const [first,source,main]=await Promise.all([vault.read(props.book.id,1),props.book.value.sourceId?vault.read<{bytes:number}>(props.book.value.sourceId):Promise.resolve(null),vault.read<MainReadingLine>(mainLineKey(props.book.id))]);if(!disposed&&store.vault===vault){added.value=first?.updatedAt||props.book.updatedAt;sourceBytes.value=source?.value.bytes??null;mainBranch.value=main?.value.branchId||null;linksReady.value=true}}catch(e){if(!disposed)error.value=(e as Error).message}})
onUnmounted(()=>{disposed=true})
</script>
<template><Sheet title="书籍详情" @close="!saving&&emit('close')"><form class="book-details" @submit.prevent="save"><header><OriginalCover :id="book.value.coverAssetId" :title="title"/><div><strong>{{book.value.chapters.length}} 章</strong><span>{{book.value.format.toUpperCase()}} · {{book.value.encoding}}</span><small>{{sourceBytes===null?'本地私人库':(sourceBytes/1024/1024).toFixed(2)+' MiB · 本地私人库'}}</small><time v-if="added">{{new Date(added).toLocaleDateString()}} 添加</time></div></header><nav v-if="linksReady" class="book-open-tools" aria-label="打开这本故事"><RouterLink :to="{path:'/local/read/'+book.id,query:{branch:mainBranch||undefined}}"><BookOpen :size="18"/>阅读</RouterLink><RouterLink :to="{path:'/local/stage/'+book.id,query:{branch:mainBranch||undefined}}"><Clapperboard :size="18"/>剧场</RouterLink><RouterLink :to="{path:'/local/lines/'+book.id,query:{branch:mainBranch||undefined}}"><GitBranch :size="18"/>故事线</RouterLink><RouterLink :to="{path:'/local/read/'+book.id,query:{branch:mainBranch||undefined,people:'1'}}"><Users :size="18"/>人物</RouterLink><RouterLink :to="{path:'/local/notebook',query:{story:book.id}}"><NotebookPen :size="18"/>笔记</RouterLink></nav><p v-if="error" class="final-error" role="alert">{{error}}</p><section v-if="latest" class="metadata-conflict" aria-label="最新书籍信息"><h3>另一个窗口已保存</h3><p>{{latest.value.title}}</p><p>{{latest.value.tags.join(' · ')}} · {{groupsOf(latest.value).join(' · ')}}</p><p>{{latest.value.pinned?'已置顶':'未置顶'}} · {{latest.value.favorite?'已收藏':'未收藏'}}</p><button type="button" :disabled="saving" @click="useLatest">保留当前输入，基于此版本重试</button></section><fieldset :disabled="saving"><label>书名<input v-model="title" maxlength="512" required></label><label>标签<input v-model="tags" maxlength="12000" placeholder="用逗号分隔"></label><label>分组<input v-model="groups" maxlength="12000" placeholder="用逗号分隔"></label><div class="book-details-flags"><label><input v-model="pinned" type="checkbox">置顶</label><label><input v-model="favorite" type="checkbox">收藏</label></div></fieldset><button type="button" :disabled="saving" @click="emit('cover')">制作封面</button><details><summary>来源校验</summary><code>{{book.value.sourceHash}}</code><small>原文段落与历史版本保留</small></details><button class="final-primary" :disabled="saving||!title.trim()">{{saving?'正在保存…':'保存'}}</button><button type="button" class="book-details-delete" :disabled="saving" @click="emit('remove')">删除书籍</button></form></Sheet></template>
<style scoped>.book-open-tools{display:flex;flex-wrap:wrap;gap:8px}.book-open-tools a{display:flex;align-items:center;gap:8px;min-height:44px;padding:10px 14px;border:1px solid var(--edge);border-radius:12px;background:var(--wash);text-decoration:none;color:var(--accent)}.book-details-delete{color:#ad3e38}.book-details{display:grid;gap:24px}.book-details header{display:flex;gap:24px;align-items:center}.book-details header>:first-child{width:105px;flex:0 0 105px}.book-details header>div{display:grid;gap:8px}.book-details header span,.book-details small,.book-details time{color:var(--muted)}.book-details fieldset{border:0;margin:0;padding:0;display:grid;gap:20px;min-width:0}.book-details input:not([type=checkbox]){width:100%;min-height:44px}.book-details-flags{display:flex;gap:32px}.book-details-flags label{display:flex;align-items:center;gap:8px;min-height:44px}.book-details input[type=checkbox]{width:20px;height:20px}.book-details summary{cursor:pointer;min-height:44px;display:flex;align-items:center}.book-details code{display:block;overflow-wrap:anywhere;font-size:12px;color:var(--muted);margin:8px 0}.book-details button{min-height:44px}</style>
